INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q1319855', 'Battle of Kirina', 'The Battle of Kirina, also known as the Battle of Krina or siege of Karina (c. 1235), was a confrontation between Sosso king Sumanguru Kanté and Mandinka prince Sundiata Keita.', 1235, NULL, NULL, NULL, NULL, NULL, 'year', '1235', 48, 'https://en.wikipedia.org/wiki/Battle_of_Kirina'),
  ('Q3486065', 'Siege of Medina Fort', 'The siege of Fort Medina took place in 1857 at Médine, on the left bank of the Senegal River in present-day Mali. The Toucouleur forces of Omar Saidou Tall unsuccessfully besieged native and French colonial troops commanded by Paul Holle.', 1857, 4, 12, 1857, 7, 18, 'day', '12 April 1857 – 18 July 1857', 34, 'https://en.wikipedia.org/wiki/Siege_of_Medina_Fort'),
  ('Q3178794', 'Tuareg rebellion (1962–1964)', 'The Tuareg rebellion of 1962–1964, sometimes called the First Tuareg Rebellion or the Alfellaga, was an insurgency by populations of what is now northern Mali begun shortly after the nation achieved independence from France in 1960. This short revolt could only be suppressed with the entry into the conflict of Morocco and Algeria in 1963, which handed over the 35 leaders of the counter-rebellion, then imposed a military authority on the Tuareg regions.', 1962, NULL, NULL, 1964, NULL, NULL, 'year', '1962–1964', 45, 'https://en.wikipedia.org/wiki/Tuareg_rebellion_(1962%E2%80%931964)'),
  ('Q4146911', '1968 Malian coup d''état', 'The 1968 Malian coup d''état was a bloodless military coup in Mali staged on 19 November 1968 against the government of President Modibo Keïta. The coup was led by Lieutenant (later Major General) Moussa Traoré, who then became the head of state.', 1968, 11, 19, NULL, NULL, NULL, 'day', '19 November 1968', 41, 'https://en.wikipedia.org/wiki/1968_Malian_coup_d''%C3%A9tat'),
  ('Q580961', 'Agacher Strip War', 'The Agacher Strip War (French: Guerre de la Bande d’Agacher), also known as the Christmas War (French: Guerre de Noël), was a brief conflict fought by Burkina Faso and Mali over a 160-kilometre-long (100 mi) strip of land along the border in northern Burkina Faso from 25 to 30 December 1985. The war ended in a ceasefire.', 1985, 12, 14, 1985, 12, 30, 'day', '14 December 1985 – 30 December 1985', 58, 'https://en.wikipedia.org/wiki/Agacher_Strip_War'),
  ('Q19955933', '1991 Malian coup d''état', 'The 26 March 1991 Malian coup d''état resulted in the overthrow of President Moussa Traoré after over two decades of dictatorship and eventually led to multi-party elections.', 1991, 3, 26, NULL, NULL, NULL, 'day', '26 March 1991', 39, 'https://en.wikipedia.org/wiki/1991_Malian_coup_d''%C3%A9tat'),
  ('Q632787', 'Insurgency in the Maghreb', 'An Islamist insurgency is taking place in the Maghreb region of North Africa, followed on from the end of the Algerian Civil War in 2002. The Algerian militant group Salafist Group for Preaching and Combat (GSPC) allied itself with al-Qaeda to eventually become al-Qaeda in the Islamic Maghreb (AQIM).', 2002, 4, 11, NULL, NULL, NULL, 'day', '11 April 2002', 58, 'https://en.wikipedia.org/wiki/Insurgency_in_the_Maghreb_(2002%E2%80%93present)'),
  ('Q2579041', '2009–2010 West African meningitis outbreak', 'The 2009–2010 West African meningitis outbreak was an epidemic of bacterial meningitis which occurred in Burkina Faso, Mali, Niger, and Nigeria since January 2009, an annual risk in the African meningitis belt. A total of 13,516 people have been infected with meningitis, and 931 have died.', 2009, 1, NULL, 2010, NULL, NULL, 'month', 'January 2009 – 2010', 43, 'https://en.wikipedia.org/wiki/2009%E2%80%932010_West_African_meningitis_outbreak'),
  ('Q875912', '2012 Malian coup d''état', 'The 2012 Malian coup d''état began on 21 March that year, when mutinying Malian soldiers, displeased with the management of the Tuareg rebellion, attacked several locations in the capital Bamako, including the presidential palace, state television, and military barracks. The soldiers, who said they had formed the National Committee for the Restoration of Democracy and State, declared the following day that they had overthrown the government of Amadou Toumani Touré, forcing him into hiding.', 2012, 4, 8, 2012, 4, 8, 'day', '8 April 2012', 59, 'https://en.wikipedia.org/wiki/2012_Malian_coup_d''%C3%A9tat'),
  ('Q1525846', '2012 Tuareg rebellion', 'The 2012 Tuareg rebellion was the early phase of the Mali War; from January to April 2012, a war was waged against the Malian government by rebels with the goal of attaining independence for the northern region of Mali, known as Azawad. It was led by the National Movement for the Liberation of Azawad (MNLA) and was part of a series of insurgencies by traditionally nomadic Tuaregs which date back at least to 1916.', 2012, NULL, NULL, NULL, NULL, NULL, 'year', '2012', 55, 'https://en.wikipedia.org/wiki/Tuareg_rebellion_(2012)'),
  ('Q2946372', 'Mali War', 'The Mali War is an ongoing conflict that began on 16 January 2012 with a Tuareg rebellion in northern Mali. The rebels included the secular-oriented National Movement for the Liberation of Azawad (MNLA), a group fighting for independence or greater autonomy of a region they called Azawad.', 2012, 1, 16, NULL, NULL, NULL, 'day', '16 January 2012', 73, 'https://en.wikipedia.org/wiki/Mali_War'),
  ('Q3181123', 'Battle of Gao', 'The Battle of Gao was fought between the National Movement for the Liberation of Azawad (MNLA) and the Islamist Movement for Oneness and Jihad in West Africa (MOJWA), along with its ally Ansar Dine, in Gao between 26 and 28 June 2012. By the 28th of June, Gao, Timbuktu and Kidal, the three biggest cities in the disputed secessionist region of Azawad within what is recognised as Malian territory, were under the control of Ansar Dine and its Islamist allies.', 2012, 6, 27, NULL, NULL, NULL, 'day', '27 June 2012', 37, 'https://en.wikipedia.org/wiki/Battle_of_Gao'),
  ('Q3560870', 'Battle of Kidal', 'The first battle of Kidal took place during the Mali war. On 30 March 2012, the city was captured by rebel MNLA and Ansar Dine forces.', 2012, 3, 26, 2012, 3, 30, 'day', '26 March 2012 – 30 March 2012', 34, 'https://en.wikipedia.org/wiki/Battle_of_Kidal_(2012)'),
  ('Q3018708', 'Battle of Konna', 'The Battle of Konna was a battle in the Northern Mali Conflict fought in January 2013 in the town of Konna in central Mali. Various Islamic fundamentalist rebels fought against the government of Mali, which was supported by French soldiers participating in Operation Serval.', 2013, 1, 10, 2013, 1, 18, 'day', '10 January 2013 – 18 January 2013', 43, 'https://en.wikipedia.org/wiki/Battle_of_Konna'),
  ('Q3276735', 'Battle of Diabaly', 'The Battle of Diabaly was fought between government forces of Mali, against groups of Islamists militants such as the AQIM and Ansar Dine. The Islamists held control of Diabaly for no longer than a week until Malian forces with the help French air strikes recaptured the town.', 2013, 1, 14, 2013, 1, 21, 'day', '14 January 2013 – 21 January 2013', 37, 'https://en.wikipedia.org/wiki/Battle_of_Diabaly'),
  ('Q5420456', 'Battle of Khalil', 'The Battle of In Khalil took place on 22–23 February 2013 and was part of the first stage of the Mali War. According to the MNLA, the first suicide bomber attempted to drive his car into a building, but the car was destroyed by fighters ahead of impact.', 2013, 2, 23, NULL, NULL, NULL, 'day', '23 February 2013', 37, 'https://en.wikipedia.org/wiki/Battle_of_In_Khalil'),
  ('Q5923961', 'Battle of Ifoghas', 'The Battle of Ifoghas, also known as the Battle of Tigharghâr or the Battle of the Ametettai, took place from 18 February to 31 March 2013, during the Northern Mali conflict. The French army and the Chadian army fought armed Salafist jihadist groups led by Al Qaeda in the Islamic Maghreb and Ansar Dine.', 2013, 2, 18, 2013, 3, 31, 'day', '18 February 2013 – 31 March 2013', 34, 'https://en.wikipedia.org/wiki/Battle_of_Ifoghas'),
  ('Q6619913', 'Battle of Iminenas', 'The Battle of Imenas was an armed confrontation between French-Malian forces and the Jihadists terrorist groups, Movement for Oneness and Jihad in West Africa and Al-Mulathameen. The battle was a decisive Franco-Malian victory, as it resulted, according to the French and the Malian governments, in 52 Islamists being killed, with no government forces being killed.', 2013, 3, 1, NULL, NULL, NULL, 'day', '1 March 2013', 34, 'https://en.wikipedia.org/wiki/Battle_of_Imenas'),
  ('Q8578070', '5th Battle of Gao', 'On March 23, 2013, a battle took place in Gao between MUJAO and Malian army. The Malian army repelled the attack.', 2013, 3, 24, NULL, NULL, NULL, 'day', '24 March 2013', 34, 'https://en.wikipedia.org/wiki/Fifth_Battle_of_Gao'),
  ('Q15989108', 'Western African Ebola virus epidemic', 'The 2013–2016 epidemic of Ebola virus disease, centered in West Africa, was the most widespread outbreak of the disease in history. It caused major loss of life and socioeconomic disruption in the region, mainly in Guinea, Liberia and Sierra Leone.', 2013, 12, NULL, 2016, 6, NULL, 'month', 'December 2013 – June 2016', 78, 'https://en.wikipedia.org/wiki/Western_African_Ebola_epidemic'),
  ('Q17410088', 'Air Algérie Flight 5017', 'Air Algérie Flight 5017 was a scheduled international passenger flight from Ouagadougou, Burkina Faso, to Algiers, Algeria, which crashed near Gossi, Mali, on 24 July 2014. The McDonnell Douglas MD-83 twinjet, operated by Spanish charter airline Swiftair for Air Algérie, disappeared from radar about fifty minutes after take-off.', 2014, 7, 24, NULL, NULL, NULL, 'day', '24 July 2014', 71, 'https://en.wikipedia.org/wiki/Air_Alg%C3%A9rie_Flight_5017'),
  ('Q21516923', '2015 Bamako hotel attack', 'On 20 November 2015, Islamist militants took 170 hostages and killed 20 of them in a mass shooting at the Radisson Blu hotel in Bamako, the capital city of Mali. The siege was ended when Malian special forces, backed by U.S. and French personnel, launched an assault on the hotel to recover the surviving hostages.', 2015, 11, 20, 2015, 11, 20, 'day', '20 November 2015', 66, 'https://en.wikipedia.org/wiki/Radisson_Blu_Bamako_attack'),
  ('Q62389968', 'March 2019 attacks against Fulani herders', 'On March 23, 2019, several attacks by gunmen killed a reported 160 Fulani herders in central Mali. The violence came in the aftermath of the Malian government cracking down on Islamic terror cells in the country.', 2019, 3, 23, NULL, NULL, NULL, 'day', '23 March 2019', 51, 'https://en.wikipedia.org/wiki/Ogossagou_massacre'),
  ('Q64526276', 'June 2019 attacks against Dogon villagers', 'On 10 June 2019, the Dogon village of Sobane Da in Mali was attacked. Moulaye Guindo, mayor of neighbouring Bankass, blamed a Fulani militia group.', 2019, 6, 9, 2019, 6, 10, 'day', '9 June 2019 – 10 June 2019', 39, 'https://en.wikipedia.org/wiki/Sobane_Da_massacre'),
  ('Q97479050', '2020 Malian protests', 'Protests in Mali began on 5 June 2020 when protesters gathered in the streets of Bamako, calling for Ibrahim Boubacar Keïta to resign as president of Mali. The protests ended after a coup d''état on 18 August 2020.', 2020, 6, 5, 2020, 8, 19, 'day', '5 June 2020 – 19 August 2020', 43, 'https://en.wikipedia.org/wiki/2020_Malian_protests'),
  ('Q98457371', '2020 Malian coup d''état', 'On 18 August 2020, elements of the Malian Armed Forces began a mutiny, and subsequently undertook a coup d''état. Soldiers on pick-up trucks stormed the Soundiata military base in the town of Kati, where gunfire was exchanged before weapons were distributed from the armory and senior officers arrested.', 2020, 8, 18, NULL, NULL, NULL, 'day', '18 August 2020', 64, 'https://en.wikipedia.org/wiki/2020_Malian_coup_d''%C3%A9tat'),
  ('Q104856693', '2020 African Sahel floods', 'In all of 2020, flooding affected 2.7 million people in 18 countries in West and Central Africa and destroyed 197,000 houses, with many regions recording excess rainfalls. The number of flood-affected people this year was more than twice the case in 2019.', 2020, 8, NULL, 2020, 9, NULL, 'month', 'August 2020 – September 2020', 37, 'https://en.wikipedia.org/wiki/2020_African_Sahel_floods'),
  ('Q106975429', '2021 Malian coup d''état', 'On the night of 24 May 2021, the Malian Army led by Vice President Assimi Goïta captured President Bah N''daw, Prime Minister Moctar Ouane and Minister of Defence Souleymane Doucouré. Assimi Goïta, the head of the junta that led the 2020 Malian coup d''état, announced that N''daw and Ouane were stripped of their powers and that new elections would be held in 2022.', 2021, 5, 24, NULL, NULL, NULL, 'day', '24 May 2021', 53, 'https://en.wikipedia.org/wiki/2021_Malian_coup_d''%C3%A9tat'),
  ('Q109924274', '2021 Mali bus massacre', 'On 3 December 2021 unidentified gunmen attacked a bus in Mopti, Central Mali, firing at its occupants and setting it on fire, killing 31 civilians and injuring 17. Most of the passengers were women travelling from Songo-Doubacore to a market in Bandiagara.', 2021, 12, 3, NULL, NULL, NULL, 'day', '3 December 2021', 34, 'https://en.wikipedia.org/wiki/Mopti_bus_massacre'),
  ('Q111480185', 'Moura massacre', 'The Moura massacre was carried out by Malian Armed Forces and Russian mercenaries from the Wagner Group between 27 and 31 March 2022, in the central Malian town of Moura, Mopti Region in conflict with Al-Qaeda in the Islamic Maghreb''s Jama''at Nasr al-Islam wal Muslimin. Over 300 civilians were killed according to Human Rights Watch.', 2022, 3, 27, 2022, 3, 31, 'day', '27 March 2022 – 31 March 2022', 43, 'https://en.wikipedia.org/wiki/Moura_massacre'),
  ('Q126961247', '2024 West African floods', 'In 2024, heavy rainfall impacted several countries across West and Central Africa, including Nigeria, Chad, Niger, Mali, Guinea, Cameroon and Ghana. At least 1,500 were killed and more than a million were displaced.', 2024, NULL, NULL, NULL, NULL, NULL, 'year', '2024', 37, 'https://en.wikipedia.org/wiki/2024_West_African_floods'),
  ('Q128007033', 'Battle of Tinzaouaten', 'The battle of Tinzaouaten was fought between the rebel coalition Strategic Framework for the Defense of the People of Azawad (CSP-DPA), and the Malian Armed Forces (FAMa) backed by the Wagner Group, a Russian state-funded mercenary group. It took place in the outskirts of Tinzaouaten, a commune near the Algeria–Mali border.', 2024, 7, 25, 2024, 7, 27, 'day', '25 July 2024 – 27 July 2024', 43, 'https://en.wikipedia.org/wiki/Battle_of_Tinzaouaten_(2024)'),
  ('Q130325301', '2024 Bamako attacks', 'On 17 September 2024, gunmen from a cell of Jama''at Nasr al-Islam wal-Muslimin (JNIM) attacked several locations across Bamako, the capital of Mali, including Malian Army and Wagner Group bases and Modibo Keita International Airport. About 100 Malian soldiers and policemen were killed and more than 255 others were injured.', 2024, 9, 17, NULL, NULL, NULL, 'day', '17 September 2024', 41, 'https://en.wikipedia.org/wiki/2024_Bamako_attacks'),
  ('Q139556342', '2026 Mali offensives', 'Since 25 April 2026, a series of joint coordinated attacks have been carried out by Azawad Liberation Front (FLA) and Jama''at Nusrat al-Islam wal-Muslimin (JNIM) across multiple locations in Mali. The JNIM fighters launched attacks in Bourem, Bamako, Kati, Sévaré, Senou and Mopti.', 2026, 4, 25, NULL, NULL, NULL, 'day', '25 April 2026', 48, 'https://en.wikipedia.org/wiki/2026_Mali_offensives');
